SELECT
    FRIEND_KEY        AS friendKey,
    REQUEST_USER_KEY  AS requestUserKey,
    TARGET_USER_KEY   AS targetUserKey,
    STATUS            AS status,
    CREATED_AT        AS createdAt,
    ACCEPTED_AT       AS acceptedAt,
    UPDATED_AT        AS updatedAt
FROM TB_FRIEND_MST
WHERE (
    REQUEST_USER_KEY = #{myUserKey}
    AND TARGET_USER_KEY = #{targetUserKey}
)
OR (
    REQUEST_USER_KEY = #{targetUserKey}
    AND TARGET_USER_KEY = #{myUserKey}
)
ORDER BY CREATED_AT DESC
LIMIT 1

mapper.update:
UPDATE TB_FRIEND_MST
    SET STATUS = 'ACCEPTED',
    ACCEPTED_AT = CURRENT_TIMESTAMP
WHERE FRIEND_KEY = #{friendKey}
    AND TARGET_USER_KEY = #{myUserKey}
    AND STATUS = 'REQUESTED'

UPDATE TB_FRIEND_MST
SET STATUS = 'REJECTED'
WHERE FRIEND_KEY = #{friendKey}
    AND TARGET_USER_KEY = #{myUserKey}
    AND STATUS = 'REQUESTED'
